{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-rFei4S/src/address.js","content":"/**
 * Cell address helpers: parsing the `COLUMNROW` shape, converting columns to
 * and from a numeric index, and ordering addresses column-major.
 */

const ADDRESS_SHAPE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parses a token that already looks like `letters` + `digits` (as produced by
 * the sheet line splitter or the formula lexer) and reports whether it names
 * an addressable cell.
 *
 * Returns `{ column, row, key }` where `column` is 1 for `A`, 26 for `Z`, 27
 * for `AA`, and so on, or `null` when the token is not one or two letters
 * followed by one to three digits naming a row of at least 1.
 */
export function parseAddress(token) {
  const match = ADDRESS_SHAPE.exec(token)
  if (!match) return null
  const [, letters, digits] = match
  const row = Number(digits)
  if (row < 1) return null
  const column = columnLettersToIndex(letters)
  const key = letters.toUpperCase() + String(row)
  return { column, row, key }
}

export function columnLettersToIndex(letters) {
  const upper = letters.toUpperCase()
  let index = 0
  for (const ch of upper) {
    index = index * 26 + (ch.charCodeAt(0) - 64)
  }
  return index
}

export function columnIndexToLetters(index) {
  let letters = ''
  let n = index
  while (n > 0) {
    const remainder = (n - 1) % 26
    letters = String.fromCharCode(65 + remainder) + letters
    n = Math.floor((n - 1) / 26)
  }
  return letters
}

/** Compares two parsed addresses: ascending column, then ascending row. */
export function compareAddresses(a, b) {
  if (a.column !== b.column) return a.column - b.column
  return a.row - b.row
}
"}

