{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-rFei4S/src/sheet.js","content":"/**
 * Parsing the sheet text format into an ordered map of declared cells.
 */

import { parseAddress } from './address.js'

/** Raised for any malformed input; `cli.js` turns this into an exit-2 message. */
export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const LEADING_WHITESPACE = /^[ \t]+/
const ADDRESS_RUN = /^[^ \t]+/
const SEPARATOR_RUN = /^[ \t]+/

/**
 * Parses sheet text into a Map from canonical address key (`A1`) to
 * `{ content, line, column, row }`, preserving declaration order.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const raw = lines[i]
    const stripped = raw.replace(LEADING_WHITESPACE, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const addressMatch = ADDRESS_RUN.exec(stripped)
    const addressToken = addressMatch[0]
    let rest = stripped.slice(addressToken.length)
    const sepMatch = SEPARATOR_RUN.exec(rest)
    const content = sepMatch ? rest.slice(sepMatch[0].length) : ''

    const upperToken = addressToken.toUpperCase()
    const parsed = parseAddress(upperToken)
    if (!parsed) {
      throw new SheetError(lineNumber, `invalid cell address ${upperToken}`)
    }
    if (cells.has(parsed.key)) {
      throw new SheetError(lineNumber, `cell ${parsed.key} is declared twice`)
    }
    cells.set(parsed.key, { content, line: lineNumber, column: parsed.column, row: parsed.row })
  }

  return cells
}
"}

