{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-rFei4S/src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after a leading `=`).
 *
 * Returns `null` when a character does not belong to any token, which the
 * parser treats the same as any other grammar failure.
 */

const NUMBER = /^[0-9]+(\.[0-9]+)?/
const WORD = /^[A-Za-z][A-Za-z0-9]*/
const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = '^*/+-=<>(),:'

export function tokenize(body) {
  const tokens = []
  let i = 0
  while (i < body.length) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }

    const rest = body.slice(i)

    const numberMatch = NUMBER.exec(rest)
    if (numberMatch) {
      tokens.push({ type: 'number', value: numberMatch[0] })
      i += numberMatch[0].length
      continue
    }

    const wordMatch = WORD.exec(rest)
    if (wordMatch) {
      tokens.push({ type: 'word', value: wordMatch[0] })
      i += wordMatch[0].length
      continue
    }

    const two = rest.slice(0, 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'op', value: two })
      i += 2
      continue
    }

    if (ONE_CHAR_OPS.includes(ch)) {
      tokens.push({ type: 'op', value: ch })
      i += 1
      continue
    }

    return null
  }
  return tokens
}
"}

