{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260919T181623Z/cell-rFei4S/src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies.
 *
 * Precedence, loosest to tightest: comparisons, then `+`/`-`, then `*`/`/`,
 * then `^` (right-associative), then a leading `+`/`-` (which binds tighter
 * than `^`). Returns `null` on any grammar failure, including leftover
 * tokens after a complete expression.
 *
 * A `word:word` pair parses as a range wherever a primary expression may
 * appear, not only as a function argument; callers decide whether a given
 * range appears directly as an argument (legal) or elsewhere (an error at
 * evaluation time, though still named for `deps`).
 */

import { tokenize } from './lexer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

export function parseFormula(body) {
  const tokens = tokenize(body)
  if (tokens === null) return null

  const state = { tokens, pos: 0 }
  const node = parseComparison(state)
  if (node === null) return null
  if (state.pos !== state.tokens.length) return null
  return node
}

function peek(state) {
  return state.tokens[state.pos] ?? null
}

function takeOp(state, value) {
  const tok = peek(state)
  if (tok && tok.type === 'op' && tok.value === value) {
    state.pos++
    return true
  }
  return false
}

function parseComparison(state) {
  let left = parseAdditive(state)
  if (left === null) return null
  for (;;) {
    const tok = peek(state)
    if (!tok || tok.type !== 'op' || !COMPARISON_OPS.has(tok.value)) break
    state.pos++
    const right = parseAdditive(state)
    if (right === null) return null
    left = { type: 'binary', op: tok.value, left, right }
  }
  return left
}

function parseAdditive(state) {
  let left = parseMultiplicative(state)
  if (left === null) return null
  for (;;) {
    const tok = peek(state)
    if (!tok || tok.type !== 'op' || (tok.value !== '+' && tok.value !== '-')) break
    state.pos++
    const right = parseMultiplicative(state)
    if (right === null) return null
    left = { type: 'binary', op: tok.value, left, right }
  }
  return left
}

function parseMultiplicative(state) {
  let left = parsePower(state)
  if (left === null) return null
  for (;;) {
    const tok = peek(state)
    if (!tok || tok.type !== 'op' || (tok.value !== '*' && tok.value !== '/')) break
    state.pos++
    const right = parsePower(state)
    if (right === null) return null
    left = { type: 'binary', op: tok.value, left, right }
  }
  return left
}

function parsePower(state) {
  const left = parseUnary(state)
  if (left === null) return null
  if (takeOp(state, '^')) {
    const right = parsePower(state)
    if (right === null) return null
    return { type: 'binary', op: '^', left, right }
  }
  return left
