 * The four value kinds a cell can hold, plus the coercions the spec defines
 * between them.
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function num(value) {
  return { type: 'number', value }
}
export function text(value) {
  return { type: 'text', value }
}
export function bool(value) {
  return { type: 'boolean', value }
}
export function err(token) {
  return { type: 'error', value: token }
}

/** Coerces an arithmetic operand: booleans become 1/0, text becomes `#VALUE!`. */
export function toNumber(value) {
  if (value.type === 'number') return value
  if (value.type === 'boolean') return num(value.value ? 1 : 0)
  if (value.type === 'error') return value
  return err('#VALUE!')
}

/** Wraps a finite arithmetic result, mapping non-finite results to `#DIV/0!`. */
export function finiteNumber(n) {
  return Number.isFinite(n) ? num(n) : err('#DIV/0!')
}

const KIND_RANK = { number: 0, text: 1, boolean: 2 }

/** Three-way compare of two non-error values per the cross-kind ordering rules. */
export function compareValues(a, b) {
  const ra = KIND_RANK[a.type]
  const rb = KIND_RANK[b.type]
  if (ra !== rb) return ra - rb
  if (a.type === 'number') return a.value - b.value
  if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  return (a.value ? 1 : 0) - (b.value ? 1 : 0)
}
"}

