 * Classifying a non-formula cell's raw content into a number, an error, or
 * text.
 */

import { ERROR_TOKENS } from './values.js'
import { num, text, err } from './values.js'

const NUMBER_LITERAL = /^-?[0-9]+(\.[0-9]+)?$/

export function parseLiteral(content) {
  if (content === '') return num(0)
  if (NUMBER_LITERAL.test(content)) return num(Number(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}
