        const from = parseAddress(node.from)
        const to = parseAddress(node.to)
        if (!from || !to) return
        const minCol = Math.min(from.column, to.column)
        const maxCol = Math.max(from.column, to.column)
        const minRow = Math.min(from.row, to.row)
        const maxRow = Math.max(from.row, to.row)
