 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { createEvaluator } from './evaluate.js'
import { parseFormula } from './parser.js'
import { collectDependencies } from './deps.js'
import { formatValue } from './format.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'values' && mode !== 'deps') {
    fail('usage: cli.js values|deps')
  }

  const input = readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (error) {
    if (error instanceof SheetError) {
      fail(`line ${error.line}: ${error.message}`)
    }
    throw error
  }

  const ordered = [...cells.entries()].sort(
    (a, b) => a[1].column - b[1].column || a[1].row - b[1].row,
  )

  const lines = []
  if (mode === 'values') {
    const evaluator = createEvaluator(cells)
    for (const [key] of ordered) {
      lines.push(`${key}=${formatValue(evaluator.getValue(key))}`)
    }
  } else {
    for (const [key, cell] of ordered) {
      const ast = cell.content.startsWith('=') ? parseFormula(cell.content.slice(1)) : null
      const deps = ast === null ? [] : collectDependencies(ast)
      lines.push(`${key}:${deps.map((d) => ` ${d}`).join('')}`)
    }
  }

  process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
}

main()
"}

